USE [JamunaBankProcurement];
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernAuthority_GetPending @EmployeeId VARCHAR(30)
AS BEGIN SET NOCOUNT ON;SELECT h.REQUISITION_ID,h.REQUISITION_NO,h.REQUESTED_DATE,h.TOTAL_ESTIMATED_AMOUNT,r.CONCERN_DIVISION_ID,ou.ORG_UNIT_NAME CONCERN_DIVISION_NAME,u.DISPLAY_NAME REQUESTED_BY_NAME,(SELECT COUNT(*)FROM dbo.REQUISITION_ITEM i WHERE i.REQUISITION_ID=h.REQUISITION_ID AND i.IS_ACTIVE=1)ITEM_COUNT FROM dbo.WORKFLOW_INSTANCE w JOIN dbo.REQUISITION_HEADER h ON h.REQUISITION_ID=w.REQUISITION_ID JOIN dbo.WORKFLOW_RULE r ON r.WORKFLOW_RULE_ID=w.WORKFLOW_RULE_ID JOIN dbo.CONCERN_DIVISION_SETUP s ON s.CONCERN_DIVISION_ID=r.CONCERN_DIVISION_ID AND s.IS_ACTIVE=1 JOIN dbo.ORG_UNIT ou ON ou.ORG_UNIT_ID=s.ORG_UNIT_ID JOIN dbo.APP_USER_CACHE u ON u.EMPLOYEE_ID=h.REQUESTED_BY_EMPLOYEE_ID JOIN dbo.CONCERN_DIVISION_AUTHORITY a ON a.CONCERN_DIVISION_ID=r.CONCERN_DIVISION_ID AND a.EMPLOYEE_ID=@EmployeeId AND a.IS_ACTIVE=1 AND a.EFFECTIVE_FROM<=CONVERT(DATE,SYSUTCDATETIME())AND(a.EFFECTIVE_TO IS NULL OR a.EFFECTIVE_TO>=CONVERT(DATE,SYSUTCDATETIME()))WHERE w.CURRENT_STAGE='CONCERN_AUTHORITY'AND w.CURRENT_STATUS='PENDING'AND w.COMPLETED_DATE IS NULL AND h.CURRENT_STATUS='IN_WORKFLOW'AND h.IS_ACTIVE=1 AND EXISTS(SELECT 1 FROM dbo.REQUISITION_ASSIGNMENT x WHERE x.REQUISITION_ID=h.REQUISITION_ID AND x.ASSIGNMENT_TYPE='CONCERN_AUTHORITY'AND x.IS_CURRENT=1 AND x.ASSIGNED_TO_ORG_UNIT_ID=s.ORG_UNIT_ID)ORDER BY h.REQUESTED_DATE;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernAuthority_Approve @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000)=NULL,@BatchReferenceId UNIQUEIDENTIFIER=NULL
AS BEGIN SET NOCOUNT ON;DECLARE @next VARCHAR(40);SELECT @next=r.DESTINATION_AFTER_CONCERN FROM dbo.WORKFLOW_INSTANCE w JOIN dbo.WORKFLOW_RULE r ON r.WORKFLOW_RULE_ID=w.WORKFLOW_RULE_ID WHERE w.REQUISITION_ID=@RequisitionId AND w.CURRENT_STAGE='CONCERN_AUTHORITY'AND w.COMPLETED_DATE IS NULL;IF @next NOT IN('READY_FOR_PROCUREMENT','PROCUREMENT_AUTHORITY')BEGIN SELECT'004'RESULT_CODE,N'No valid matrix-defined destination exists after Concern Authority approval.'RESULT_MESSAGE,@RequisitionId ENTITY_ID,NULL REFERENCE_NO;RETURN;END;DECLARE @result TABLE(RESULT_CODE VARCHAR(3),RESULT_MESSAGE NVARCHAR(4000),ENTITY_ID BIGINT,REFERENCE_NO VARCHAR(100));INSERT @result EXEC dbo.usp_Workflow_Advance @RequisitionId,@ActorEmployeeId,'CONCERN_AUTHORITY','CONCERN_AUTHORITY_APPROVE','CONCERN_AUTHORITY',@next,@Remarks,@BatchReferenceId;SELECT RESULT_CODE,RESULT_MESSAGE,ENTITY_ID,CASE WHEN RESULT_CODE='000'THEN @next ELSE REFERENCE_NO END REFERENCE_NO FROM @result;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernAuthority_Return @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000),@BatchReferenceId UNIQUEIDENTIFIER=NULL
AS BEGIN SET NOCOUNT ON;IF NULLIF(LTRIM(RTRIM(@Remarks)),'')IS NULL BEGIN SELECT'001'RESULT_CODE,N'Remarks are required for return.'RESULT_MESSAGE,@RequisitionId ENTITY_ID,NULL REFERENCE_NO;RETURN;END;DECLARE @result TABLE(RESULT_CODE VARCHAR(3),RESULT_MESSAGE NVARCHAR(4000),ENTITY_ID BIGINT,REFERENCE_NO VARCHAR(100));INSERT @result EXEC dbo.usp_Workflow_Advance @RequisitionId,@ActorEmployeeId,'CONCERN_AUTHORITY','CONCERN_AUTHORITY_RETURN','CONCERN_AUTHORITY','CONCERN_DIVISION',@Remarks,@BatchReferenceId;SELECT RESULT_CODE,RESULT_MESSAGE,ENTITY_ID,CASE WHEN RESULT_CODE='000'THEN'CONCERN_DIVISION'ELSE REFERENCE_NO END REFERENCE_NO FROM @result;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernAuthority_Reject @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000),@BatchReferenceId UNIQUEIDENTIFIER=NULL
AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;BEGIN TRY BEGIN TRAN;IF NULLIF(LTRIM(RTRIM(@Remarks)),'')IS NULL THROW 51000,'Remarks are required for rejection.',1;DECLARE @rule BIGINT,@division BIGINT;SELECT @rule=w.WORKFLOW_RULE_ID,@division=r.CONCERN_DIVISION_ID FROM dbo.WORKFLOW_INSTANCE w WITH(UPDLOCK,HOLDLOCK)JOIN dbo.WORKFLOW_RULE r ON r.WORKFLOW_RULE_ID=w.WORKFLOW_RULE_ID WHERE w.REQUISITION_ID=@RequisitionId AND w.CURRENT_STAGE='CONCERN_AUTHORITY'AND w.CURRENT_STATUS='PENDING'AND w.COMPLETED_DATE IS NULL;IF @rule IS NULL THROW 51003,'Requisition is not pending with a Concern Authority.',1;IF NOT EXISTS(SELECT 1 FROM dbo.CONCERN_DIVISION_AUTHORITY WHERE CONCERN_DIVISION_ID=@division AND EMPLOYEE_ID=@ActorEmployeeId AND IS_ACTIVE=1 AND EFFECTIVE_FROM<=CONVERT(DATE,SYSUTCDATETIME())AND(EFFECTIVE_TO IS NULL OR EFFECTIVE_TO>=CONVERT(DATE,SYSUTCDATETIME())))THROW 51002,'Actor is not an active authority for this Concern Division.',1;IF NOT EXISTS(SELECT 1 FROM dbo.REQUISITION_HEADER WHERE REQUISITION_ID=@RequisitionId AND CURRENT_STATUS='IN_WORKFLOW'AND IS_ACTIVE=1)THROW 51003,'Invalid workflow state.',1;UPDATE dbo.REQUISITION_ASSIGNMENT SET IS_CURRENT=0,RELEASED_DATE=SYSUTCDATETIME()WHERE REQUISITION_ID=@RequisitionId AND IS_CURRENT=1;UPDATE dbo.REQUISITION_HEADER SET CURRENT_STATUS='REJECTED',MODIFIED_BY=@ActorEmployeeId,MODIFIED_DATE=SYSUTCDATETIME()WHERE REQUISITION_ID=@RequisitionId;UPDATE dbo.WORKFLOW_INSTANCE SET CURRENT_STAGE='END',CURRENT_OWNER_TYPE='NONE',CURRENT_OWNER_EMPLOYEE_ID=NULL,CURRENT_OWNER_ORG_UNIT_ID=NULL,CURRENT_STATUS='REJECTED',COMPLETED_DATE=SYSUTCDATETIME(),MODIFIED_DATE=SYSUTCDATETIME()WHERE REQUISITION_ID=@RequisitionId AND CURRENT_STAGE='CONCERN_AUTHORITY'AND COMPLETED_DATE IS NULL;INSERT dbo.APPROVAL_ACTION(REQUISITION_ID,ACTION_TYPE,ACTION_BY_EMPLOYEE_ID,ACTION_ROLE,FROM_STAGE,TO_STAGE,REMARKS,BATCH_REFERENCE_ID)VALUES(@RequisitionId,'CONCERN_AUTHORITY_REJECT',@ActorEmployeeId,'CONCERN_AUTHORITY','CONCERN_AUTHORITY','END',@Remarks,@BatchReferenceId);INSERT dbo.WORKFLOW_HISTORY(REQUISITION_ID,WORKFLOW_RULE_ID,FROM_STAGE,TO_STAGE,ACTION_TYPE,ACTION_BY_EMPLOYEE_ID,REMARKS,BATCH_REFERENCE_ID)VALUES(@RequisitionId,@rule,'CONCERN_AUTHORITY','END','CONCERN_AUTHORITY_REJECT',@ActorEmployeeId,@Remarks,@BatchReferenceId);COMMIT;SELECT'000'RESULT_CODE,N'Success'RESULT_MESSAGE,@RequisitionId ENTITY_ID,'END'REFERENCE_NO;END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK;SELECT CASE ERROR_NUMBER()WHEN 51000 THEN'001'WHEN 51002 THEN'003'WHEN 51003 THEN'004'ELSE'999'END RESULT_CODE,ERROR_MESSAGE()RESULT_MESSAGE,@RequisitionId ENTITY_ID,NULL REFERENCE_NO;END CATCH END;
GO
